import{createHomeState,reduceHomeState}from'./home-first-page-state.js';import{configureHomeEarthView,cameraSnapshot,resolveExistingEarthusViewer}from'./home-cesium-adapter.js';const CAT=[['EARTH','지구','◉'],['WEATHER','기상','☁'],['OCEAN','해양','≈'],['HAZARD','재난','△'],['HUMAN','인간 흐름','⋮'],['SPACE','우주','✦']];const el=(t,c,x='')=>{const n=document.createElement(t);if(c)n.className=c;if(x)n.textContent=x;return n};const coord=(v,p,n)=>Number.isFinite(v)?`${Math.abs(v).toFixed(3)}° ${v>=0?p:n}`:'—';const alt=m=>Number.isFinite(m)?m>=1000?`${Math.round(m/1000).toLocaleString()} km`:`${Math.round(m)} m`:'—';
export function mountEarthus2FirstPage({root=document.body,viewer=null,onAction=()=>{}}={}){const real=resolveExistingEarthusViewer(viewer);configureHomeEarthView(real);let state=createHomeState();const shell=el('div','e2-home');shell.dataset.earthus2Home='true';shell.innerHTML=`<header class="e2-topbar"><button class="e2-brand" data-home><i></i><span>EARTHUS</span></button><button class="e2-search" data-search><span>⌕</span><b>장소·국가 검색</b><kbd>⌘ K</kbd></button><div class="e2-top-actions"><button data-location>◎ <span>내 위치</span></button><button data-account aria-label="계정">○</button></div></header><nav class="e2-rail" aria-label="데이터 영역"></nav><div class="e2-live"><i></i><strong>LIVE EARTH</strong><span>현재 지구</span></div><button class="e2-intelligence-tab" data-intelligence><span>EARTH INTELLIGENCE</span><i>›</i></button><aside class="e2-intelligence" hidden><header><b>EARTH INTELLIGENCE</b><button data-intelligence-close>×</button></header><nav><button class="is-active">NOW</button><button>WHY</button><button>NEXT</button><button>FOR ME</button></nav><div class="e2-intel-empty"><strong>지구를 선택하면 분석이 열립니다.</strong><span>공식 관측·예보와 Earthus 분석을 분리해 표시합니다.</span></div></aside><div class="e2-camera"><span data-lat>—</span><span data-lon>—</span><span class="accent" data-alt>—</span></div><div class="e2-timeline"><button class="is-active">NOW</button><span>레이어 선택 시 시간축 활성화</span></div><div class="e2-evidence"><span>NO LAYER SELECTED</span><b>공식 데이터 레이어를 선택하세요</b></div>`;root.appendChild(shell);const rail=shell.querySelector('.e2-rail');for(const[id,label,icon]of CAT){const b=el('button');b.type='button';b.dataset.category=id;b.innerHTML=`<span>${icon}</span><em>${label}</em>`;if(id==='EARTH')b.classList.add('is-active');rail.appendChild(b)}const update=()=>{const c=cameraSnapshot(real);shell.querySelector('[data-lat]').textContent=coord(c.latitude,'N','S');shell.querySelector('[data-lon]').textContent=coord(c.longitude,'E','W');shell.querySelector('[data-alt]').textContent=`ALT ${alt(c.altitudeM)}`};let last=0;const post=()=>{const now=performance.now();if(now-last>250){last=now;update()}};real.scene.postRender?.addEventListener?.(post);update();const render=()=>{shell.querySelector('.e2-intelligence').hidden=!state.intelligenceOpen;shell.querySelector('.e2-intelligence-tab').hidden=state.intelligenceOpen};const dispatch=a=>{state=reduceHomeState(state,a);render();onAction(a,state)};shell.querySelector('[data-home]').onclick=()=>dispatch({type:'CLEAR_LAYER'});shell.querySelector('[data-intelligence]').onclick=()=>dispatch({type:'INTELLIGENCE_TOGGLE'});shell.querySelector('[data-intelligence-close]').onclick=()=>dispatch({type:'INTELLIGENCE_TOGGLE'});shell.querySelector('[data-search]').onclick=()=>onAction({type:'OPEN_SEARCH'},state);shell.querySelector('[data-location]').onclick=()=>onAction({type:'USE_LOCATION'},state);rail.onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;rail.querySelectorAll('button').forEach(x=>x.classList.toggle('is-active',x===b));onAction({type:'OPEN_CATEGORY',category:b.dataset.category},state)};const key=e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();onAction({type:'OPEN_SEARCH'},state)}if(e.key==='Escape'&&state.intelligenceOpen)dispatch({type:'INTELLIGENCE_TOGGLE'})};window.addEventListener('keydown',key);return Object.freeze({get state(){return state},shell,destroy(){window.removeEventListener('keydown',key);real.scene.postRender?.removeEventListener?.(post);shell.remove()}})}
